11	/**
12	 * Everyone an agent may mention from a thread without notifying a stranger.
13	 *
14	 * Three sources, each best-effort and each read separately so a failure of one
15	 * does not take the others with it:
16	 *
17	 *   - whoever opened the issue or pull request
18	 *   - whoever has commented on it
19	 *   - the repository's collaborators
20	 *
21	 * The `issues` endpoint rather than `gh issue view`, because a pull request is an
22	 * issue to that endpoint and is not to that command -- one call that works for
23	 * both beats two that each work for half.
24	 *
25	 * An empty result is the fail-closed case and is correct: nothing confirmed means
26	 * nothing is exempt, and `domain/work/mention.ts` explains why that is the cheaper of
27	 * the two mistakes.
28	 */
29	export function knownParticipants(repo: string, number: string | number): string[] {
30	  if (!repo || !String(number).trim()) return [];
31	  const logins = new Set<string>();
32	
33	  const collect = (args: string[], read: (json: unknown) => unknown[]) => {
34	    const { code, stdout } = gh(...args);
35	    if (code !== 0) return;
36	    try {
37	      for (const login of read(JSON.parse(stdout))) {
38	        if (typeof login === "string" && login) logins.add(login);
39	      }
40	    } catch {
41	      // A body that will not parse tells us nothing about who may be mentioned.
42	    }
43	  };
44	
45	  collect(["api", `repos/${repo}/issues/${number}`], (json) => [
46	    (json as { user?: { login?: string } }).user?.login,
47	  ]);
48	  collect(["api", `repos/${repo}/issues/${number}/comments`, "--paginate"], (json) =>
49	    (json as { user?: { login?: string } }[]).map((comment) => comment.user?.login),
50	  );
51	  collect(["api", `repos/${repo}/collaborators`, "--paginate"], (json) =>
52	    (json as { login?: string }[]).map((person) => person.login),
53	  );
54	
55	  return [...logins];
56	}

